console.log(`[SUCCESS] Deposit (other user): ${depB.transactionId}`)

console.log('\n[PROCESS] Step 3: Reading the on-chain leaves and generating a Groth16 proof with snarkjs...')
await sleep(5000)
const [leavesRaw] = await mirrorCall(poolId, poolIface, 'getLeaves')
const leaves = leavesRaw.map(BigInt)
const myIndex = leaves.findIndex((l) => l === myCommitment)
if (myIndex < 0) throw new Error('Your commitment is not in the on-chain tree yet')
