console.log(`[EXPLORER] ${getHashscanUrl(withdrawTx)}`)
await sleep(6000)
const after = await getMirrorHbarTinybars(recipient.accountId.toString())
console.log(`[VERIFY] Recipient ${recipient.accountId} received ${after - before} tinybars; calldata revealed only root + nullifierHash, not the leaf.`)

    console.log('\n[PROCESS] Step 6: Replaying the same proof (double spend)...')
    let replay = 'UNEXPECTED_SUCCESS'
    try {
      await (await execute(client, poolId, poolIface, 'withdraw', [a, b, c, root, nullifierHash, recipientAddress], { gas: 600_000 })).getReceipt(client)
    } catch (err) { replay = err.status ? err.status.toString() : err.message }
    console.log(`[EXPECTED FAILURE] Double spend rejected: ${replay}`)
    if (replay === 'UNEXPECTED_SUCCESS') throw new Error('Double spend was accepted')

    updateState('ZK_LAST_WITHDRAW_TX_ID', withdrawTx.transactionId.toString())

    console.log('\n KEY CONCEPT:')
    console.log('The Groth16 proof convinced the contract that you own one of the deposits')
    console.log('without revealing which one: the link between depositor and recipient is hidden.')

    console.log('\n--- SESSION COMPLETE ---')
